function formContent(value){
 if(!value||typeof value!=='object')return value;
 const known=FORM_CONTENT_TRANSLATIONS[value.zh];if(!known)return value;
 return Object.fromEntries(['zh','en','es','vi'].map(l=>[l,value[l]||known[l]||'']));
}
function formText(key){return t(key);}
function formHtml(key){return formContentHtml(translations[key]);}
function formContentHtml(value){
 const v=formContent(value),main=translated(v,primary),second=secondary&&secondary!==primary?translated(v,secondary):'';
 return esc(main).replaceAll('\n','<br>')+(second?'<small class="secondary-note" lang="'+esc(secondary)+'"> / '+esc(second).replaceAll('\n','<br>')+'</small>':'');
}
